import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"概括归纳","description":"","frontmatter":{},"headers":[],"relativePath":"shenlun/gaikuo-guina.md","filePath":"shenlun/gaikuo-guina.md"}'),r={name:"shenlun/gaikuo-guina.md"};function d(l,a,i,o,h,p){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="概括归纳" tabindex="-1">概括归纳 <a class="header-anchor" href="#概括归纳" aria-label="Permalink to &quot;概括归纳&quot;">​</a></h1><p>概括归纳是申论最基础的题型，也是最容易拿分的题型。</p><blockquote><p>🎯 <strong>核心原则</strong>：所有答案都在材料里，你不要创造，你只负责找和整理。</p></blockquote><h2 id="🔧-解题步骤" tabindex="-1">🔧 解题步骤 <a class="header-anchor" href="#🔧-解题步骤" aria-label="Permalink to &quot;🔧 解题步骤&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 审题 → 明确概括对象、范围、字数要求</span></span>
<span class="line"><span>2. 阅读 → 边读边划关键词句</span></span>
<span class="line"><span>3. 归类 → 同类项合并，形成 3-5 个大点</span></span>
<span class="line"><span>4. 书写 → 总括句 + 分述</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="📝-答题模板" tabindex="-1">📝 答题模板 <a class="header-anchor" href="#📝-答题模板" aria-label="Permalink to &quot;📝 答题模板&quot;">​</a></h2><h3 id="标准格式" tabindex="-1">标准格式 <a class="header-anchor" href="#标准格式" aria-label="Permalink to &quot;标准格式&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【总括句】X方面的情况/问题/原因如下：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. [要点一概括]：具体内容...</span></span>
<span class="line"><span>2. [要点二概括]：具体内容...</span></span>
<span class="line"><span>3. [要点三概括]：具体内容...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="常用总括句" tabindex="-1">常用总括句 <a class="header-anchor" href="#常用总括句" aria-label="Permalink to &quot;常用总括句&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题目类型</th><th>总括句模板</th></tr></thead><tbody><tr><td>概括问题</td><td>&quot;X（方面/领域）存在以下问题：&quot;</td></tr><tr><td>概括原因</td><td>&quot;造成X的原因是多方面的：&quot;</td></tr><tr><td>概括影响</td><td>&quot;X带来的影响主要体现在：&quot;</td></tr><tr><td>概括做法</td><td>&quot;X在Y方面采取了以下措施：&quot;</td></tr><tr><td>概括变化</td><td>&quot;X呈现以下变化趋势：&quot;</td></tr></tbody></table><hr><h2 id="⚡-常见问题与对策" tabindex="-1">⚡ 常见问题与对策 <a class="header-anchor" href="#⚡-常见问题与对策" aria-label="Permalink to &quot;⚡ 常见问题与对策&quot;">​</a></h2><h3 id="问题1-照抄原材料" tabindex="-1">问题1：照抄原材料 <a class="header-anchor" href="#问题1-照抄原材料" aria-label="Permalink to &quot;问题1：照抄原材料&quot;">​</a></h3><p>❌ 直接整句抄材料<br> ✅ 提取关键词，用自己的话重组</p><h3 id="问题2-遗漏要点" tabindex="-1">问题2：遗漏要点 <a class="header-anchor" href="#问题2-遗漏要点" aria-label="Permalink to &quot;问题2：遗漏要点&quot;">​</a></h3><p>❌ 写完了发现材料里还有没用到的信息<br> ✅ 边读边编号，确保每个要点都不漏</p><h3 id="问题3-归类混乱" tabindex="-1">问题3：归类混乱 <a class="header-anchor" href="#问题3-归类混乱" aria-label="Permalink to &quot;问题3：归类混乱&quot;">​</a></h3><p>❌ 把不同类的东西放一起，前后交叉<br> ✅ 归纳时按&quot;主体&quot;&quot;领域&quot;&quot;性质&quot;分类</p><h3 id="问题4-过度拔高" tabindex="-1">问题4：过度拔高 <a class="header-anchor" href="#问题4-过度拔高" aria-label="Permalink to &quot;问题4：过度拔高&quot;">​</a></h3><p>❌ 材料说的是具体问题，答案写成了大道理<br> ✅ 忠实于材料，不要上升高度</p><hr><h2 id="📋-常见归纳维度" tabindex="-1">📋 常见归纳维度 <a class="header-anchor" href="#📋-常见归纳维度" aria-label="Permalink to &quot;📋 常见归纳维度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>示例</th></tr></thead><tbody><tr><td>按主体</td><td>政府、企业、社会、个人</td></tr><tr><td>按领域</td><td>经济、政治、文化、社会、生态</td></tr><tr><td>按流程</td><td>事前、事中、事后</td></tr><tr><td>按性质</td><td>主观原因/客观原因、内因/外因</td></tr><tr><td>按层面</td><td>思想层面、制度层面、技术层面、资金层面</td></tr></tbody></table><hr><h2 id="📝-练习记录" tabindex="-1">📝 练习记录 <a class="header-anchor" href="#📝-练习记录" aria-label="Permalink to &quot;📝 练习记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>题目</th><th>要点数</th><th>遗漏</th><th>心得</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table>`,26)])])}const c=t(r,[["render",d]]);export{b as __pageData,c as default};
